 43	     * 
 44	     * @param The class type of the object that is wanted.
 45	     */
 46	    public <T> T getObject(Class<T> objectType) 
 47	    {
 48	        Object exactMatch = occupants.get(objectType);
 49	        if (objectType.isInstance(exactMatch)) {
 50	            return objectType.cast(exactMatch);
 51	        }
 52	
